<?php require_once dirname(__DIR__).'/includes/functions.php';require_content_manager();$rows=$con->query('SELECT * FROM skills ORDER BY name');$pageTitle='Skills';require __DIR__.'/includes/header.php';?><div class="d-flex justify-content-between mb-3"><div><h1 class="h3">Skills</h1><p class="text-muted">Maintain reusable career skills.</p></div><button class="btn btn-primary create-action" data-bs-toggle="modal" data-bs-target="#editModal"><i class="bi bi-plus-circle"></i><span>Add skill</span></button></div><div class="card table-responsive"><table class="table mb-0"><thead><tr><th>Name</th><th></th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><button class="btn btn-sm btn-outline-primary edit" data-id="<?=$r['id']?>" data-name="<?=e($r['name'])?>">Edit</button></td></tr><?php endforeach?></tbody></table></div><div class="modal fade" id="editModal"><div class="modal-dialog"><form class="modal-content" action="<?=url('admin/save.php')?>" method="post" data-ajax><div class="modal-header"><h2 class="modal-title fs-5">Skill</h2><button class="btn-close" data-bs-dismiss="modal"></button></div><div class="modal-body"><input type="hidden" name="csrf" value="<?=csrf_token()?>"><input type="hidden" name="entity" value="skill"><input type="hidden" name="id"><label class="form-label">Name</label><input class="form-control" name="name" required maxlength="80"></div><div class="modal-footer"><button class="btn btn-primary">Save</button></div></form></div></div><script>document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{let f=document.querySelector('#editModal form');f.id.value=b.dataset.id;f.name.value=b.dataset.name;bootstrap.Modal.getOrCreateInstance(editModal).show()})</script><?php require __DIR__.'/includes/footer.php';?>
